func mintTo(cur realm, caller address, name, imageURL string) int {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if paused {
		panic("col: paused")
	}
	if maxSupply > 0 && minted >= maxSupply {
		panic("col: sold out")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(imageURL) {
		panic("col: image")
	}
	nextID++
	id := nextID
	it := &item{
		id:       id,
		name:     name,
		image:    imageURL,
		owner:    caller,
		rarity:   rarityOf(id),
		revealed: true,
		slot:     -1,
	}
	items.Set(itemKey(id), it)
	err := ledger.Mint(caller, itemTid(id))
	if err != nil {
		panic("col: mint")
	}
	minted++
	factory.NoteMinted(cross(cur), minted)
	return id
}

