	return slug
}

func ItemLine(id int) string {
	it := mustItem(id)
	return strconv.Itoa(it.id) + "|" + it.name + "|" + it.owner.String() + "|" + it.seller.String() + "|" + strconv.FormatInt(it.price, 10) + "|" + strconv.FormatBool(it.listed) + "|" + it.image + "|" + slug + "|" + it.rarity + "|" + it.traits + "|" + strconv.FormatBool(it.revealed) + "|" + strconv.Itoa(it.slot)
}

func ListOpen() string {
	requireInit()
	out := ""
	n := 0
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if !it.listed {
			return false
		}
		if n >= 50 {
			return true
		}
		if out != "" {
			out += "\n"
		}
		out += ItemLine(it.id)
		n++
		return false
	})
	return out
}

func TokensOf(owner string) string {
	requireInit()
	who := address(owner)
	if !who.IsValid() {
		return ""
	}
	out := ""
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if it.owner != who {
			return false
		}
		if out != "" {
			out += ","
		}
		out += strconv.Itoa(it.id)
		return false
	})
	return out
}

func TokenOfOwnerByIndex(owner string, index int64) string {
	requireInit()
	who := address(owner)
	if !who.IsValid() {
		panic("col: addr")
	}
	if index < 0 {
		panic("col: index")
	}
	var n int64
	found := ""
	items.Iterate("", "", func(_ string, value any) bool {
		it := value.(*item)
		if it.owner != who {
			return false
		}
		if n == index {
			found = strconv.Itoa(it.id)
			return true
		}
		n++
		return false
	})
	if found == "" {
		panic("col: index")
	}
	return found
}

func TokenByIndex(index int64) string {
	requireInit()
	if index < 0 {
		panic("col: index")
	}
	var n int64
	found := ""
	items.Iterate("", "", func(_ string, value any) bool {
		if n == index {
			found = strconv.Itoa(value.(*item).id)
			return true
		}
		n++
		return false
	})
	if found == "" {
		panic("col: index")
	}
	return found
}

func Creator() string {
	requireInit()
	return creator.String()
}

func MintPrice() int64 {
	requireInit()
	return mintPrice
}

func MaxSupply() int {
	requireInit()
	return maxSupply
}

func Minted() int {
	requireInit()
	return minted
}

func RoyaltyBps() int {
	requireInit()
	return royaltyBps
}

func SetRoyalty(cur realm, bps int) {
	caller := requireUser(cur)
	if caller != creator {
		panic("col: not creator")
	}
	if minted != 0 {
		panic("col: minted")
	}
	if bps < 0 || bps > maxRoyaltyBps {
		panic("col: royalty")
	}
	royaltyBps = bps
	factory.NoteRoyalty(cross(cur), bps)
	chain.Emit("SetRoyalty", "slug", slug, "bps", strconv.Itoa(bps))
}

func RarityOf(id int) string {
	return mustItem(id).rarity
}

func TraitsOf(id int) string {
	return mustItem(id).traits
}

func Render(_ string) string {
	if !inited {
		return "# Collection\n\nCall Init first.\n"
	}
	out := "# " + colName + " ($" + colSymbol + ")\n\n"
	out += "- minted: " + strconv.Itoa(minted) + "\n"
	out += "- mint price: " + strconv.FormatInt(mintPrice, 10) + " ugnot\n\n"
	open := ListOpen()
	if open == "" {
		out += "_No open listings._\n"
	} else {
		out += "```\n" + open + "\n```\n"
	}
	return out
}

func mintTo(cur realm, caller address, name, imageURL string) int {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if paused {
		panic("col: paused")
	}
	if maxSupply > 0 && minted >= maxSupply {
		panic("col: sold out")
	}
	if !validName(name) {
		panic("col: name")
	}
	if !validImage(imageURL) {
		panic("col: image")
	}
	nextID++
	id := nextID
	it := &item{
		id:       id,
		name:     name,
		image:    imageURL,
		owner:    caller,
		rarity:   rarityOf(id),
		revealed: true,
		slot:     -1,
	}
	items.Set(itemKey(id), it)
	err := ledger.Mint(caller, itemTid(id))
	if err != nil {
		panic("col: mint")
	}
	minted++
	factory.NoteMinted(cross(cur), minted)
	return id
}

func takeLaunchFee(cur realm) {
	fee := factory.LaunchFee()
	who := factory.ReservedCreator(lastElem(cur.PkgPath()))
	if who != "" && who == cur.Previous().Address().String() {
		takeExact(0)
		return
	}
	takeExact(fee)
	if fee > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), factory.Address(), chain.Coins{{Denom: nativeDenom, Amount: fee}})
	}
}

func takeExact(want int64) {
	sent := unsafe.OriginSend()
	if want == 0 {
		if len(sent) != 0 {
			panic("col: extra denoms")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != nativeDenom || sent[0].Amount != want {
		panic("col: wrong payment")
	}
}

func publicImage() string {
	img := "/samples/" + slug + "-0" + strconv.Itoa(minted+1) + ".png"
	if validImage(img) {
		return img
	}
	return colCover
}

func requireInit() {
	if !inited {
		panic("col: call Init first")
	}
}

func requireUser(cur realm) address {
	requireInit()
	if !cur.IsCurrent() {
		panic("col: spoofed realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("col: EOA only")
	}
	return cur.Previous().Address()
}

func itemTid(id int) grc721.TokenID {
	return grc721.TokenID(strconv.Itoa(id))
}

func parseTid(tid string) int {
	id, err := strconv.Atoi(tid)
	if err != nil || id < 1 {
		panic("col: tid")
	}
	return id
}

func mustItem(id int) *item {
	v := items.Get(itemKey(id))
	if v == nil {
		panic("col: unknown item")
	}
	return v.(*item)
}

func itemKey(id int) string {
	return strconv.Itoa(id)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("col: pkg")
	}
	return pkg[i+1:]
}

func slotKey(i int) string {
	return strconv.Itoa(i)
}

func slotCap() int {
	if maxSupply > 0 {
		return maxSupply
	}
	return dropSlotHardCap
}

func applySlot(id int, s *dropSlot, slotIndex int) {
	it := mustItem(id)
	it.name = s.name
	it.image = s.image
	if s.rarity != "" {
		it.rarity = s.rarity
	}
	it.traits = s.traits
	it.revealed = true
	it.slot = slotIndex
	items.Set(itemKey(id), it)
}

func writeTokenMeta(id int) {
	it := mustItem(id)
	uri := tokenJSON(it)
	if metaLed == nil {
		return
	}
	if err := metaLed.SetTokenURI(itemTid(id), uri); err != nil {
		panic("col: tokenURI")
	}
	if err := metaLed.SetTokenMetadata(itemTid(id), metadata.Data{
		Name:        it.name,
		Description: colName + " #" + strconv.Itoa(id),
		Image:       absImage(it.image),
		Attributes:  traitAttrs(it),
	}); err != nil {
		panic("col: metadata")
	}
}

func tokenJSON(it *item) string {
	attrs := ""
	for _, tr := range traitAttrs(it) {
		if attrs != "" {
			attrs += ","
		}
		attrs += `{"trait_type":` + jsonStr(tr.TraitType) + `,"value":` + jsonStr(tr.Value) + `}`
	}
	body := `{"name":` + jsonStr(it.name) + `,"description":` + jsonStr(colName+" #"+strconv.Itoa(it.id)) + `,"image":` + jsonStr(absImage(it.image)) + `,"attributes":[` + attrs + `]}`
	return "data:application/json;charset=utf-8," + pctURI(body)
}

func traitAttrs(it *item) []metadata.Trait {
	out := []metadata.Trait{}
	if it.rarity != "" {
		out = append(out, metadata.Trait{TraitType: "Rarity", Value: it.rarity})
	}
	for _, part := range strings.Split(it.traits, ";") {
		part = strings.TrimSpace(part)
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			continue
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			continue
		}
		out = append(out, metadata.Trait{TraitType: key, Value: val})
	}
	return out
}

func absImage(u string) string {
	if u == "" {
		return u
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") || strings.HasPrefix(u, "ipfs://") {
		return u
	}
	if strings.HasPrefix(u, "/") {
		return publicOrigin + u
	}
	return u
}

func jsonStr(s string) string {
	out := `"`
	for _, r := range s {
		switch r {
		case '"':
			out += `\"`
		case '\\':
			out += `\\`
		case '\n':
			out += `\n`
		case '\r':
			out += `\r`
		case '\t':
			out += `\t`
		default:
			if r < 0x20 {
				out += `\u00`
				hex := "0123456789abcdef"
				out += string([]byte{hex[r>>4], hex[r&15]})
			} else {
				out += string(r)
			}
		}
	}
	return out + `"`
}

func pctURI(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' {
			out += string(c)
			continue
		}
		hex := "0123456789ABCDEF"
		out += "%"
		out += string([]byte{hex[c>>4], hex[c&15]})
	}
	return out
}

func splitDropLines(blob string) []string {
	raw := strings.Split(blob, "\n")
	out := make([]string, 0, len(raw))
	for _, line := range raw {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		out = append(out, line)
	}
	return out
}

func parseDropLine(line string) (string, string, string, string) {
	parts := strings.Split(line, "|")
	name := ""
	image := ""
	rarity := ""
	traits := ""
	if len(parts) > 0 {
		name = strings.TrimSpace(parts[0])
	}
	if len(parts) > 1 {
		image = strings.TrimSpace(parts[1])
	}
	if len(parts) > 2 {
		rarity = strings.TrimSpace(parts[2])
	}
	if len(parts) > 3 {
		traits = strings.TrimSpace(parts[3])
	}
	return name, image, rarity, traits
}

func validRarity(s string) bool {
	if s == "" {
		return true
	}
	return s == "Common" || s == "Uncommon" || s == "Rare" || s == "Epic" || s == "Legendary"
}

func validTraits(s string) bool {
	if s == "" {
		return true
	}
	if len(s) > 200 {
		return false
	}
	if strings.ContainsAny(s, "\n\r|") {
		return false
	}
	n := 0
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		colon := strings.Index(part, ":")
		if colon <= 0 || colon >= len(part)-1 {
			return false
		}
		key := strings.TrimSpace(part[:colon])
		val := strings.TrimSpace(part[colon+1:])
		if key == "" || val == "" {
			return false
		}
		if !asciiSet(key, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		if !asciiSet(val, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-") {
			return false
		}
		n++
		if n > 8 {
			return false
		}
	}
	return n >= 1
}

func validPkgName(s string) bool {
	if len(s) < minSlugLen || len(s) > grc721.MaxSymbolLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func rarityOf(id int) string {
	r := id % 10
	if r == 0 {
		return "Legendary"
	}
	if r == 1 {
		return "Common"
	}
	if r == 2 {
		return "Uncommon"
	}
	if r == 3 {
		return "Rare"
	}
	if r == 4 {
		return "Epic"
	}
	if r <= 7 {
		return "Uncommon"
	}
	return "Common"
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	if strings.ContainsAny(name, "\n\r|\t\"\\") {
		return false
	}
	for _, r := range name {
		if r < 0x20 {
			return false
		}
	}
	return true
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}

package bazaarv1

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	pkgPath          = "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/bazaar/bazaarv1"
	nativeDenom      = "ugnot"
	defaultLaunchFee = int64(10_000_000) // 10 GNOT
	maxNameLen       = 64
	maxImageLen      = 200
	maxSupplyBound   = 1_000_000
	maxRoyaltyBps    = 1000
	maxSymbolLen     = 11
	maxSlugLen         = 11
	minSlugLen         = 2
	defaultProtocolBps = int64(200) // 2% Magic Eden
	maxProtocolBps     = int64(500)
)

type collection struct {
	slug       string
	name       string
	symbol     string
	cover      string
	pkg        string
	creator    address
	maxSupply  int
	mintPrice  int64
	minted     int
	royaltyBps int
}

var (
	bySlug    avl.Tree
	byPkg     avl.Tree
	pending   avl.Tree
	reserved  avl.Tree
	inited    bool
	admin     address
	self      address
	launchFee   int64
	protocolBps int64
	seenBank    int64
)

func Init(cur realm) {
	if inited {
		panic("factory: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	admin = cur.Previous().Address()
	self = cur.Address()
	bySlug = avl.Tree{}
	byPkg = avl.Tree{}
	pending = avl.Tree{}
	reserved = avl.Tree{}
	launchFee = defaultLaunchFee
	protocolBps = defaultProtocolBps
	seenBank = bankUgnot()
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

func Address() address {
	return chain.PackageAddress(pkgPath)
}

func LaunchFee() int64 {
	requireInit()
	return launchFee
}

func Admin() string {
	requireInit()
	return admin.String()
}

func SetLaunchFee(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot < 0 {
		panic("factory: launch fee")
	}
	launchFee = ugnot
	chain.Emit("SetLaunchFee", "ugnot", strconv.FormatInt(ugnot, 10))
}

func ProtocolBps() int64 {
	requireInit()
	if protocolBps <= 0 {
		return defaultProtocolBps
	}
	return protocolBps
}

func SetProtocolBps(cur realm, bps int64) {
	requireAdmin(cur)
	if bps < 0 || bps > maxProtocolBps {
		panic("factory: protocol bps")
	}
	protocolBps = bps
	chain.Emit("SetProtocolBps", "bps", strconv.FormatInt(bps, 10))
}

func CreditLaunchFee(cur realm) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	pkg := prev.PkgPath()
	if pending.Has(pkg) {
		panic("factory: already credited")
	}
	if byPkg.Has(pkg) {
		panic("factory: already registered")
	}
	now := bankUgnot()
	if now < seenBank {
		panic("factory: bank")
	}
	if now-seenBank != launchFee {
		panic("factory: launch fee")
	}
	seenBank = now
	pending.Set(pkg, true)
	chain.Emit("CreditLaunchFee", "pkg", pkg)
}

func Register(cur realm, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	requireInit()
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	creatorRlm := prev.Previous()
	if !creatorRlm.IsUserCall() {
		panic("factory: EOA creator")
	}
	pkg := prev.PkgPath()
	slug := lastElem(pkg)
	if reserved.Has(slug) {
		who := reserved.Get(slug).(address)
		if creatorRlm.Address() != who {
			panic("factory: reserved")
		}
		reserved.Remove(slug)
		if pending.Has(pkg) {
			pending.Remove(pkg)
		}
	} else {
		if !pending.Has(pkg) {
			panic("factory: launch fee")
		}
		pending.Remove(pkg)
	}
	register(pkg, creatorRlm.Address(), name, symbol, cover, maxSupply, mintPrice, royaltyBps)
}

func Reserve(cur realm, slug string) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !validSlug(slug) {
		panic("factory: slug")
	}
	if bySlug.Has(slug) || reserved.Has(slug) {
		panic("factory: slug taken")
	}
	takeFactorySend(launchFee)
	seenBank = bankUgnot()
	reserved.Set(slug, cur.Previous().Address())
	chain.Emit("Reserve", "slug", slug)
}

func CancelReserve(cur realm, slug string) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !reserved.Has(slug) {
		panic("factory: not reserved")
	}
	who := reserved.Get(slug).(address)
	if who != cur.Previous().Address() {
		panic("factory: not reserver")
	}
	if bySlug.Has(slug) {
		panic("factory: already registered")
	}
	reserved.Remove(slug)
	if launchFee > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(self, who, chain.Coins{{Denom: nativeDenom, Amount: launchFee}})
	}
	seenBank = bankUgnot()
	chain.Emit("CancelReserve", "slug", slug)
}

func ReservedCreator(slug string) string {
	requireInit()
	slug = strings.ToLower(strings.TrimSpace(slug))
	if !reserved.Has(slug) {
		return ""
	}
	return reserved.Get(slug).(address).String()
}

func takeFactorySend(want int64) {
	sent := unsafe.OriginSend()
	if want == 0 {
		if len(sent) != 0 {
			panic("factory: extra denoms")
		}
		return
	}
	if len(sent) != 1 || sent[0].Denom != nativeDenom || sent[0].Amount != want {
		panic("factory: wrong payment")
	}
}

func NoteMinted(cur realm, n int) {
	requireInit()
	if n < 0 {
		panic("factory: minted")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.minted = n
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func NoteRoyalty(cur realm, bps int) {
	requireInit()
	if bps < 0 || bps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("factory: collection realm")
	}
	c := mustByPkg(prev.PkgPath())
	c.royaltyBps = bps
	byPkg.Set(c.pkg, c)
	bySlug.Set(c.slug, c)
}

func CollectionOf(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return c.pkg
}

func CollectionAddr(slug string) string {
	requireInit()
	c := mustBySlug(slug)
	return chain.PackageAddress(c.pkg).String()
}

func RoyaltyOf(slug string) int {
	requireInit()
	c := mustBySlug(slug)
	return c.royaltyBps
}

func ListCollections() string {
	requireInit()
	out := ""
	bySlug.Iterate("", "", func(_ string, value any) bool {
		c := value.(*collection)
		if out != "" {
			out += "\n"
		}
		out += c.slug + "|" + c.name + "|" + c.cover + "|" + c.pkg + "|" + strconv.FormatInt(c.mintPrice, 10) + "|" + strconv.Itoa(c.maxSupply) + "|" + strconv.Itoa(c.minted) + "|" + c.creator.String() + "|" + chain.PackageAddress(c.pkg).String() + "|" + strconv.Itoa(c.royaltyBps)
		return false
	})
	return out
}

func Withdraw(cur realm) {
	requireAdmin(cur)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	ugnot := bk.GetCoins(self).AmountOf(nativeDenom)
	if ugnot <= 0 {
		panic("factory: no funds")
	}
	seenBank = 0
	bk.SendCoins(self, admin, chain.Coins{{Denom: nativeDenom, Amount: ugnot}})
	chain.Emit("Withdraw", "amount", strconv.FormatInt(ugnot, 10))
}

func TransferAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !next.IsValid() {
		panic("factory: invalid address")
	}
	if next == admin {
		panic("factory: already admin")
	}
	admin = next
	chain.Emit("TransferAdmin", "addr", next.String())
}

func Render(_ string) string {
	if !inited {
		return "# Bazaar factory\n\nCall Init first.\n"
	}
	out := "# Bazaar factory\n\n"
	out += "- launch fee: " + strconv.FormatInt(launchFee, 10) + " ugnot\n"
	out += "- collections: " + strconv.Itoa(bySlug.Size()) + "\n\n"
	lines := ListCollections()
	if lines == "" {
		out += "_No collections._\n"
	} else {
		out += "```\n" + lines + "\n```\n"
	}
	return out
}

func register(pkg string, creator address, name, symbol, cover string, maxSupply int, mintPrice, royaltyBps int64) {
	if !strings.HasPrefix(pkg, "gno.land/r/") {
		panic("factory: pkg")
	}
	slug := lastElem(pkg)
	if !validSlug(slug) {
		panic("factory: slug")
	}
	if !validName(name) {
		panic("factory: name")
	}
	if !validSymbol(symbol) {
		panic("factory: symbol")
	}
	if !validImage(cover) {
		panic("factory: cover")
	}
	if maxSupply < 0 || maxSupply > maxSupplyBound {
		panic("factory: maxSupply")
	}
	if mintPrice < 0 {
		panic("factory: mintPrice")
	}
	if royaltyBps < 0 || royaltyBps > maxRoyaltyBps {
		panic("factory: royalty")
	}
	if bySlug.Has(slug) {
		panic("factory: slug taken")
	}
	if byPkg.Has(pkg) {
		panic("factory: pkg already registered")
	}
	c := &collection{
		slug:       slug,
		name:       name,
		symbol:     symbol,
		cover:      cover,
		pkg:        pkg,
		creator:    creator,
		maxSupply:  maxSupply,
		mintPrice:  mintPrice,
		royaltyBps: int(royaltyBps),
	}
	bySlug.Set(slug, c)
	byPkg.Set(pkg, c)
	chain.Emit("Register", "slug", slug, "pkg", pkg, "creator", creator.String())
}

func requireInit() {
	if !inited {
		panic("factory: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("factory: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("factory: not admin")
	}
}

func bankUgnot() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(nativeDenom)
}

func mustBySlug(slug string) *collection {
	v := bySlug.Get(slug)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func mustByPkg(pkg string) *collection {
	v := byPkg.Get(pkg)
	if v == nil {
		panic("factory: unknown collection")
	}
	return v.(*collection)
}

func lastElem(pkg string) string {
	i := strings.LastIndex(pkg, "/")
	if i < 0 || i+1 >= len(pkg) {
		panic("factory: pkg")
	}
	return pkg[i+1:]
}

func validSlug(s string) bool {
	if len(s) < minSlugLen || len(s) > maxSlugLen {
		return false
	}
	if s[0] < 'a' || s[0] > 'z' {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyz0123456789")
}

func validSymbol(s string) bool {
	if len(s) < 1 || len(s) > maxSymbolLen {
		return false
	}
	return asciiSet(s, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > maxNameLen {
		return false
	}
	return !strings.ContainsAny(name, "\n\r|")
}

func validImage(u string) bool {
	if u == "" {
		return true
	}
	if len(u) > maxImageLen {
		return false
	}
	if strings.ContainsAny(u, " \t\n\r|<>\"'`") {
		return false
	}
	if strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://") {
		return true
	}
	const prefix = "/samples/"
	if !strings.HasPrefix(u, prefix) {
		return false
	}
	rest := u[len(prefix):]
	if rest == "" {
		return false
	}
	return asciiSet(rest, "abcdefghijklmnopqrstuvwxyz0123456789._-")
}

func asciiSet(s, allowed string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(allowed, rune(s[i])) {
			return false
		}
	}
	return true
}
